// Oeste BlockTestimonials — Topanga block (v0.4.8).
// A full page section composed from Oeste components, inlined below so
// this file is self-contained. Copy-paste ready. Requires: React 18+,
// Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/blocks.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/blocks/testimonials
import React from "react";

const BADGE_TONES = {
  neutral: "border-[#1c1917]/20 text-[#1c1917] dark:border-[#f5f3ef]/20 dark:text-[#f5f3ef]",
  accent: "border-[#c47d3b]/40 bg-[#c47d3b]/10 text-[#1c1917] dark:border-[#db914e]/40 dark:bg-[#db914e]/10 dark:text-[#f5f3ef]",
  success: "border-[#2f6b3a]/40 bg-[#2f6b3a]/10 text-[#2f6b3a] dark:border-[#6ba368]/40 dark:bg-[#6ba368]/10 dark:text-[#6ba368]",
  danger: "border-[#a83e22]/40 bg-[#a83e22]/10 text-[#a83e22] dark:border-[#e07a52]/40 dark:bg-[#e07a52]/10 dark:text-[#e07a52]",
};

export function Avatar({ src, name, alt, size = "md" }) {
  const initials = name.split(/\s+/).map((w) => w[0]).filter(Boolean).slice(0, 2).join("").toUpperCase();
  const [failed, setFailed] = React.useState(false);
  const dims = size === "lg" ? "h-16 w-16 text-lg" : "h-11 w-11 text-sm";
  return (
    <span title={name} role="img" aria-label={name}
      className={`inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-[#c47d3b] font-bold text-[#1c1917] dark:bg-[#db914e] dark:text-[#1c1917] ${dims}`}>
      {src && !failed
        ? <img src={src} alt={alt || name} onError={() => setFailed(true)} className="h-full w-full object-cover" />
        : <span aria-hidden="true">{initials}</span>}
    </span>
  );
}

export function Badge({ children, tone = "neutral" }) {
  return <span className={`inline-flex min-h-8 items-center rounded-full border px-3 py-1 text-xs font-semibold ${BADGE_TONES[tone]}`}>{children}</span>;
}

export function Card({ title, children, headingLevel = 3 }) {
  const id = React.useId();
  const Heading = `h${headingLevel}`;
  return (
    <section aria-labelledby={id} className="rounded-lg border border-[#1c1917]/10 bg-[#fcfaf7] p-6 text-[#1c1917] shadow-[0_1px_2px_rgba(28,25,23,0.06)] dark:border-[#f5f3ef]/10 dark:bg-[#1c1917] dark:text-[#f5f3ef]">
      <Heading id={id} className="text-xl font-medium">{title}</Heading>
      <div className="mt-3">{children}</div>
    </section>
  );
}

export function BlockTestimonials() {
  const quotes = [
    { quote: "We stopped losing decisions in chat threads. Every call we make on a project sits on its page, and clients read the same page we do.", name: "Maya Chen", role: "Studio lead, Alder Studio", badge: "Studio plan" },
    { quote: "Bringing a freelancer in takes an afternoon now. They read the project page and start; nobody has to brief them from memory.", name: "Jonas Weber", role: "Producer, Northlight", badge: null },
    { quote: "Our end-of-project reviews write themselves. The page already holds what happened, in the order it happened, with the reasons attached.", name: "Priya Nair", role: "Founder, Fern and Co", badge: null },
  ];
  return (
    <section className="bg-[#f6f4f1] px-6 py-16 text-[#1c1917] dark:bg-[#121110] dark:text-[#f5f3ef] lg:px-8 lg:py-24">
      <div className="mx-auto max-w-[1200px]">
        <div className="max-w-[640px]">
          <Badge tone="accent">Customers</Badge>
          <h2 className="mt-4 text-[1.75rem] font-semibold leading-tight tracking-[-0.025em] lg:text-[2.5rem]">Studios that switched, in their words</h2>
          <p className="mt-4 leading-relaxed text-[#706963] dark:text-[#9e968f]">Three studios on what changed once every project had one page.</p>
        </div>
        <div className="mt-10 grid items-start gap-6 lg:grid-cols-3">
          {quotes.map((q) => (
            <Card key={q.name} title={q.name} headingLevel={3}>
              <blockquote>
                <p className="leading-relaxed">{q.quote}</p>
              </blockquote>
              <footer className="mt-5 flex items-center gap-3">
                <Avatar name={q.name} />
                <p className="text-sm text-[#706963] dark:text-[#9e968f]">{q.role}</p>
              </footer>
              {q.badge ? (
                <p className="mt-4">
                  <Badge tone="neutral">{q.badge}</Badge>
                </p>
              ) : null}
            </Card>
          ))}
        </div>
      </div>
    </section>
  );
}
